# Veterinary Biostatistics App
# Full standalone Shiny application
# Version: 3.4.8
# Made by Markus Hodal Drag
# Date: 2026-11-06
# v3.4.8: post-hoc results are saved to the results cart from inside the post-hoc table.
# v3.4.7: Cliff's delta and Hodges-Lehmann question marks sit in the column names. The multiple-outcome plot grows with the number of rows, including when the card is enlarged.
# v3.4.6: smaller interface type, and the results-table notice is removed.
# v3.4.5: question-mark help for Cliff's delta and the Hodges-Lehmann difference, and a post-hoc results download.
# v3.4.4: integer scores report Cliff's delta with a confidence interval. The median score difference is often 0 when most scores are 0.
# v3.4.3: the Explore plot and analysis summary use about half the page.
# v3.4.2: the multiple-outcome default uses each outcome's own test and Holm family, so adjusted P matches the individual analysis.
# v3.4.1: multiple-outcome plot shows adjusted P; effect sizes stay in the tables; the multiplicity family defaults to within each outcome.
# v3.4.0: multiple-outcome non-parametric comparisons, shared Holm adjustment, effect sizes, and Explore descriptive statistics.
# v3.3.20: forest-green header with pig, chicken, cow, goat, and sheep silhouettes. Light text on the dark bar.
# v3.3.19: states that the app is provided as is, with no warranty, and that the author accepts no responsibility for its use.
# v3.3.18: verifies transformed values reach inference, reports original-versus-analysis-scale summaries, and explains invariant rank-test P values.
# v3.3.17: makes numeric transformation explicit and auditable across plots, tests, adjusted models, exports, axis labels, QC, and reproducible code.
# v3.3.16: Minimal plot style restores the conventional vertical Y-axis title orientation.
# v3.3.15: Clean journal remains default with both vertical and horizontal grid lines off by default.
# v3.3.14: Clean journal remains default; style presets are redesigned to be clearly distinguishable in axes, backgrounds, typography, grids, and legend placement.
# v3.3.13: plot-style presets, grid controls, explicit HEX group colours, and adjustable PCA/MDS group ellipses.
# v3.3.12: repairs all CFU strategy initialization, supports numeric or explicit Yes/No detection columns, and prevents transient [object Object] errors.
# v3.3.11: separates postmortem incidence, positive-score severity, and full multi-tissue profile; removes duplicate postmortem tables.
# v3.3.10: postmortem strategies now replace the generic Kruskal-Wallis/Dunn summary with the actual Fisher-exact odds-ratio forest analysis.
# v3.3.9: rewrites result help popups to explain interpretation, units, null values, and practical meaning rather than repeating column names.
# v3.3.8: separates ML coefficient/importance tables from odds-ratio and variable-importance plots.
# v3.3.7: Explore full-output cart action, prominent PCA/MDS variable caption control, clear fixed-effect definitions, and rpart.plot decision trees with fallback.
# v3.3.6: transparent strategy specifications, package/session metadata in saved outputs, PCA/MDS variable caption, and improved manuscript-ready exports.
# v3.3.5: plain-language question-mark help for the PCA/MDS map, explained variance, and loadings.
# v3.3.4: PCA/MDS point size defaults to 1, jitter defaults to 10%, and the map card retains its full-screen enlarge control.
# v3.3.3: robust grouping-variable detection; postmortem and CFU strategies prioritize treatment/group/arm variables and never default to animal IDs.
# v3.3.2: stable postmortem tissue strategy initialization, automatic reference selection, manual reset, PCA jitter %, synchronized logistic S-curve predictor, and concise help.
# v3.2.1: example data updated
# v3.2.0: strategy wiring, multivariate/ML plot carts, model-output cart repairs, and robustness audit corrections.
# v3.0.1: synthetic XLSX example workbook and one-click example session.
# v3.0.0: PCA/MDS, classification models, browser forest, and results/code cart.
# v2.9.15: Dunn test is computed in the app, and the theme uses a system font so Shinylive does not download Google fonts.
# v2.3: restored Get data power planning with explicit named-group comparison and historical-data estimates.
# v2.2: ordered included groups; first level is model reference; removed levels are excluded.
# v1.6.7: fixed horizontal raincloud labels: dependent variable on X, grouping variable on Y.
# v1.6.6: emmeans means table, random-effect interpretation, optional profile CIs.
# v1.6.5: restored adjustable sparse-group exclusion controls and QC reporting.
# v1.6.4: explicit emmeans/Tukey labelling and robust coefficient-table columns.
#
# Run with:
#   shiny::runApp()
#
# Upload a CSV or Excel file from the sidebar. The app does not ship with data.

required_packages <- c(
  "shiny", "bslib", "DT", "dplyr", "tidyr", "purrr", "readr",
  "readxl", "writexl", "ggplot2", "ggdist", "ragg", "svglite",
  "scales", "tibble", "multcompView", "emmeans", "lme4", "broom.mixed", "zip", "colourpicker", "rpart"
)

# rpart.plot is optional for clearer tree diagrams; a base-rpart fallback preserves Shinylive compatibility.
options(repos = c(CRAN = "https://cloud.r-project.org"))
# Shinylive already has the packages. install.packages() there talks to CRAN,
# which has no webR build, and the page sits on the loading screen.
on_webr <- grepl("emscripten", R.version$platform, ignore.case = TRUE)
missing_packages <- setdiff(required_packages, rownames(installed.packages()))
if (!on_webr && length(missing_packages)) {
  install.packages(
    missing_packages,
    dependencies = c("Depends", "Imports", "LinkingTo")
  )
}
still_missing <- setdiff(required_packages, rownames(installed.packages()))
if (length(still_missing)) {
  stop("Missing package(s): ", paste(still_missing, collapse = ", "))
}

invisible(lapply(required_packages, library, character.only = TRUE))

# ---------- Helpers -----------------------------------------------------------
`%||%` <- function(x, y) if (is.null(x) || length(x) == 0) y else x

fmt_p <- function(x) {
  ifelse(
    !is.finite(x),
    "Not estimable",
    ifelse(x < 0.001, "<0.001", sprintf("%.3f", x))
  )
}

safe_name <- function(x) {
  x <- gsub("[^A-Za-z0-9_-]+", "_", x)
  x <- gsub("_+", "_", x)
  trimws(x, whitespace = "_")
}

read_user_data <- function(path, name) {
  extension <- tolower(tools::file_ext(name))
  if (extension == "csv") {
    readr::read_csv(path, show_col_types = FALSE)
  } else if (extension %in% c("xlsx", "xls")) {
    readxl::read_excel(path)
  } else {
    stop("Upload a CSV, XLSX, or XLS file.")
  }
}

palette_values <- function(name, n) {
  base <- switch(
    name,
    "Journal blue–plum–teal" = c(
      "#4C78A8", "#9C6A9E", "#59A5A5", "#D4A72C",
      "#7A8A99", "#8E6C8A", "#6B8E85", "#B07AA1"
    ),
    "Okabe–Ito" = c(
      "#0072B2", "#CC79A7", "#009E73", "#E69F00",
      "#56B4E9", "#D55E00", "#F0E442", "#000000"
    ),
    "Viridis discrete" = scales::viridis_pal(option = "D")(max(3, n)),
    "Nord" = c(
      "#5E81AC", "#B48EAD", "#8FBCBB", "#D08770",
      "#81A1C1", "#A3BE8C", "#EBCB8B", "#88C0D0"
    ),
    c("#4C78A8", "#9C6A9E", "#59A5A5")
  )
  if (length(base) < n) grDevices::colorRampPalette(base)(n) else base[seq_len(n)]
}

wilson_ci <- function(events, n, conf.level = 0.95) {
  z <- stats::qnorm(1 - (1 - conf.level) / 2)
  p <- events / n
  denominator <- 1 + z^2 / n
  centre <- (p + z^2 / (2 * n)) / denominator
  half_width <- z * sqrt(p * (1 - p) / n + z^2 / (4 * n^2)) / denominator
  c(
    lower = max(0, centre - half_width),
    upper = min(1, centre + half_width)
  )
}

cliffs_delta <- function(x, y) {
  x <- x[is.finite(x)]
  y <- y[is.finite(y)]
  nx <- length(x)
  ny <- length(y)
  if (!nx || !ny) return(NA_real_)
  if (nx * ny <= 250000) {
    gt <- sum(outer(x, y, FUN = `>`))
    lt <- sum(outer(x, y, FUN = `<`))
    return((gt - lt) / (nx * ny))
  }
  wt <- suppressWarnings(stats::wilcox.test(x, y, exact = FALSE))
  W <- unname(wt$statistic)
  U <- W - nx * (nx + 1) / 2
  (2 * U) / (nx * ny) - 1
}

location_contrast <- function(x, y) {
  x <- x[is.finite(x)]
  y <- y[is.finite(y)]
  out <- list(estimate = NA_real_, lower = NA_real_, upper = NA_real_, p = NA_real_, delta = cliffs_delta(x, y))
  if (!length(x) || !length(y)) return(out)
  fit <- tryCatch(
    suppressWarnings(stats::wilcox.test(x, y, exact = FALSE, conf.int = TRUE, conf.level = 0.95)),
    error = function(e) NULL
  )
  if (is.null(fit)) {
    fit <- tryCatch(suppressWarnings(stats::wilcox.test(x, y, exact = FALSE)), error = function(e) NULL)
    if (!is.null(fit)) out$p <- fit$p.value
    return(out)
  }
  out$estimate <- unname(fit$estimate)
  out$lower <- unname(fit$conf.int[1])
  out$upper <- unname(fit$conf.int[2])
  out$p <- fit$p.value
  out
}

integer_scores <- function(x) {
  x <- x[is.finite(x)]
  length(x) > 0 && all(abs(x - round(x)) < 1e-8)
}

cliffs_delta_ci <- function(x, y, conf.level = 0.95, n_boot = 400) {
  x <- x[is.finite(x)]
  y <- y[is.finite(y)]
  point <- cliffs_delta(x, y)
  out <- c(estimate = point, lower = NA_real_, upper = NA_real_)
  if (!is.finite(point) || length(x) < 2 || length(y) < 2) return(out)
  if (length(x) * length(y) > 50000) n_boot <- min(n_boot, 200)
  seed <- suppressWarnings(as.integer((sum(x) * 10007 + sum(y) * 17 + length(x) * 13) %% 2147483646))
  if (!is.finite(seed) || seed <= 0) seed <- 1L
  old_seed <- if (exists(".Random.seed", envir = globalenv(), inherits = FALSE)) get(".Random.seed", envir = globalenv()) else NULL
  on.exit({
    if (is.null(old_seed)) {
      if (exists(".Random.seed", envir = globalenv(), inherits = FALSE)) rm(".Random.seed", envir = globalenv())
    } else {
      assign(".Random.seed", old_seed, envir = globalenv())
    }
  }, add = TRUE)
  set.seed(seed)
  boots <- replicate(n_boot, cliffs_delta(sample(x, replace = TRUE), sample(y, replace = TRUE)))
  alpha <- (1 - conf.level) / 2
  qs <- stats::quantile(boots, c(alpha, 1 - alpha), na.rm = TRUE, names = FALSE)
  c(estimate = point, lower = unname(qs[1]), upper = unname(qs[2]))
}

score_effect_label <- function(x, y, loc) {
  if (!integer_scores(c(x, y))) {
    return(paste0(fmt_num(loc$estimate), " (", fmt_interval(loc$lower, loc$upper), ")"))
  }
  ci <- cliffs_delta_ci(x, y)
  paste0("Cliff ", fmt_num(ci[["estimate"]], 2), " (", fmt_interval(ci[["lower"]], ci[["upper"]], 2), ")")
}

fmt_num <- function(x, digits = 3) {
  ifelse(is.finite(x), sprintf(paste0("%.", digits, "f"), x), "")
}

fmt_interval <- function(lower, upper, digits = 3) {
  ifelse(is.finite(lower) & is.finite(upper), sprintf(paste0("%.", digits, "f–%.", digits, "f"), lower, upper), "")
}

adjust_in_families <- function(p, family, method = "holm") {
  method <- method %||% "holm"
  if (!length(p)) return(numeric())
  if (identical(method, "none")) return(p)
  family <- as.character(family)
  family[is.na(family) | !nzchar(family)] <- "ungrouped"
  out <- rep(NA_real_, length(p))
  for (nm in unique(family)) {
    idx <- which(family == nm)
    out[idx] <- stats::p.adjust(p[idx], method = method)
  }
  out
}

numeric_group_summary <- function(y, g, outcome = NULL) {
  ok <- is.finite(y) & !is.na(g)
  y <- y[ok]
  g <- droplevels(factor(g[ok]))
  if (!length(y) || !nlevels(g)) return(tibble::tibble())
  purrr::map_dfr(levels(g), function(nm) {
    z <- y[g == nm]
    q <- stats::quantile(z, c(0.25, 0.75), names = FALSE)
    mean_ci <- if (length(z) >= 2 && is.finite(stats::sd(z)) && stats::sd(z) > 0) {
      unname(stats::t.test(z)$conf.int)
    } else c(NA_real_, NA_real_)
    tibble::tibble(
      Outcome = outcome %||% "",
      Group = nm,
      n = length(z),
      Mean = mean(z),
      SD = stats::sd(z),
      `Mean 95% CI` = fmt_interval(mean_ci[1], mean_ci[2]),
      Median = stats::median(z),
      `IQR (Q1–Q3)` = fmt_interval(q[1], q[2])
    )
  })
}

transform_outcome <- function(x, transformation, offset = 1) {
  x <- as.numeric(x)
  if (transformation == "Square root" && any(x < 0, na.rm=TRUE)) stop("Square-root transformation cannot be applied to negative values.")
  if (transformation %in% c("log10(x + offset)","ln(x + offset)") && any(x + offset <= 0, na.rm=TRUE)) stop("Log transformation requires x + offset > 0 for every retained row.")
  switch(transformation,"None"=x,"log10(x + offset)"=log10(x+offset),"ln(x + offset)"=log(x+offset),"Square root"=sqrt(x),"Rank"=rank(x,na.last="keep",ties.method="average"),x)
}

long_test_result <- function(test_name, statistic = NA_real_, df = NA_character_, p = NA_real_) {
  tibble::tibble(
    Test = test_name,
    Statistic = ifelse(is.finite(statistic), sprintf("%.3f", statistic), ""),
    df = as.character(df %||% ""),
    `P value` = fmt_p(p)
  )
}

pairwise_fisher <- function(data, group, binary, adjust_method) {
  levels_group <- levels(droplevels(data[[group]]))
  if (length(levels_group) < 2) return(tibble::tibble())
  pairs <- utils::combn(levels_group, 2, simplify = FALSE)
  purrr::map_dfr(pairs, function(g) {
    z <- data[data[[group]] %in% g, , drop = FALSE]
    fit <- tryCatch(stats::fisher.test(table(droplevels(z[[group]]), z[[binary]])), error=function(e) NULL)
    tibble::tibble(
      group1 = g[1], group2 = g[2], Comparison = paste(g[2], "vs", g[1]),
      OR = if (is.null(fit)) NA_real_ else unname(fit$estimate),
      Lower = if (is.null(fit)) NA_real_ else fit$conf.int[1],
      Upper = if (is.null(fit)) NA_real_ else fit$conf.int[2],
      p_raw = if (is.null(fit)) NA_real_ else fit$p.value
    )
  }) |>
    dplyr::mutate(
      p_adjusted = stats::p.adjust(p_raw, method = adjust_method),
      `OR (95% CI)` = ifelse(is.finite(OR)&is.finite(Lower)&is.finite(Upper), sprintf("%.2f (%.2f–%.2f)",OR,Lower,Upper),"Not estimable"),
      `Raw P` = fmt_p(p_raw), `Adjusted P` = fmt_p(p_adjusted)
    )
}

pairwise_numeric <- function(data, group, outcome, method, adjust_method) {
  levels_group <- levels(droplevels(data[[group]]))
  if (length(levels_group) < 2) return(tibble::tibble())
  pairs <- utils::combn(levels_group, 2, simplify = FALSE)
  purrr::map_dfr(pairs, function(g) {
    z <- data[data[[group]] %in% g, , drop = FALSE]
    fit <- tryCatch(switch(method,
      "Mann-Whitney-Wilcoxon"=suppressWarnings(stats::wilcox.test(z[[outcome]]~droplevels(z[[group]]),exact=FALSE)),
      "Welch t-test"=stats::t.test(z[[outcome]]~droplevels(z[[group]]),var.equal=FALSE),
      "Pooled t-test"=stats::t.test(z[[outcome]]~droplevels(z[[group]]),var.equal=TRUE),
      suppressWarnings(stats::wilcox.test(z[[outcome]]~droplevels(z[[group]]),exact=FALSE))
    ), error=function(e) NULL)
    tibble::tibble(group1=g[1],group2=g[2],Comparison=paste(g[2],"vs",g[1]),p_raw=if(is.null(fit)) NA_real_ else fit$p.value)
  }) |>
    dplyr::mutate(p_adjusted=stats::p.adjust(p_raw,method=adjust_method),`Raw P`=fmt_p(p_raw),`Adjusted P`=fmt_p(p_adjusted))
}

pairwise_dunn <- function(data, adjust_method = "holm") {
  # Dunn (1964) on the pooled Kruskal-Wallis ranks.
  # Pair order and z sign match rstatix::dunn_test: group1 is the earlier
  # level, group2 the later level, and z is mean rank of group2 minus group1.
  # Computed here so the app does not load rstatix. That package pulls in
  # Deriv, which has no webR binary, and Shinylive export then stops.
  x <- data$.outcome
  g <- droplevels(factor(data$.group))
  ok <- is.finite(x) & !is.na(g)
  x <- x[ok]
  g <- droplevels(g[ok])
  lv <- levels(g)
  if (length(lv) < 2 || length(x) < 2) return(tibble::tibble())

  ranks <- rank(x)
  mean_ranks <- tapply(ranks, g, mean)
  grp_sizes <- tapply(x, g, length)
  n <- length(x)
  ranks_sorted <- sort(ranks)
  pos <- 1
  tiesum <- 0
  while (pos <= n) {
    nt <- sum(ranks_sorted == ranks_sorted[pos])
    pos <- pos + nt
    if (nt > 1) tiesum <- tiesum + nt^3 - nt
  }
  tie_c <- tiesum / (12 * (n - 1))

  rows <- vector("list", length(lv) * (length(lv) - 1) / 2)
  k <- 0
  for (j in seq_along(lv)[-length(lv)]) {
    for (i in (j + 1):length(lv)) {
      k <- k + 1
      dif <- unname(mean_ranks[i] - mean_ranks[j])
      se <- sqrt((n * (n + 1) / 12 - tie_c) * (1 / grp_sizes[i] + 1 / grp_sizes[j]))
      rows[[k]] <- tibble::tibble(
        group1 = lv[j],
        group2 = lv[i],
        statistic = dif / se,
        p = 2 * stats::pnorm(abs(dif / se), lower.tail = FALSE)
      )
    }
  }
  out <- dplyr::bind_rows(rows)
  out$p.adj <- stats::p.adjust(out$p, method = adjust_method)

  tibble::tibble(
    group1 = out$group1,
    group2 = out$group2,
    Comparison = paste(out$group2, "vs", out$group1),
    statistic = out$statistic,
    p_raw = out$p,
    p_adjusted = out$p.adj,
    `Dunn z` = sprintf("%.3f", out$statistic),
    `Raw P` = fmt_p(out$p),
    `Adjusted P` = fmt_p(out$p.adj)
  )
}

pairwise_emmeans <- function(data, method, control_group = NULL,
                               outcome_type = "Numeric") {
  model_data <- data |>
    dplyr::transmute(.outcome = .outcome, .group = droplevels(.group))

  fit <- if (outcome_type == "Binary") {
    stats::glm(.outcome ~ .group, family = stats::binomial(), data = model_data)
  } else {
    stats::lm(.outcome ~ .group, data = model_data)
  }

  emm <- emmeans::emmeans(fit, ~ .group)

  if (method == "Tukey HSD") {
    contrast_grid <- emmeans::contrast(emm, method = "pairwise", adjust = "tukey")
    result <- as.data.frame(summary(contrast_grid, infer = c(TRUE, TRUE)))
  } else {
    shiny::validate(shiny::need(
      !is.null(control_group) && control_group %in% levels(model_data$.group),
      "Select a valid Dunnett control group."
    ))
    ref_index <- match(control_group, levels(model_data$.group))
    contrast_grid <- emmeans::contrast(
      emm, method = "trt.vs.ctrl", ref = ref_index, adjust = "mvt"
    )
    result <- as.data.frame(summary(contrast_grid, infer = c(TRUE, TRUE)))
  }

  # emmeans contrast labels are written as "A - B".
  split_labels <- strsplit(as.character(result$contrast), " - ", fixed = TRUE)
  group1 <- vapply(split_labels, `[`, character(1), 1)
  group2 <- vapply(split_labels, `[`, character(1), 2)

  tibble::tibble(
    group1 = group1,
    group2 = group2,
    Comparison = paste(group1, "vs", group2),
    estimate = result$estimate,
    lower = result$lower.CL,
    upper = result$upper.CL,
    p_raw = NA_real_,
    p_adjusted = result$p.value,
    `Estimate (95% CI)` = sprintf(
      "%.3f (%.3f–%.3f)", result$estimate, result$lower.CL, result$upper.CL
    ),
    `Raw P` = "—",
    `Adjusted P` = fmt_p(result$p.value)
  )
}

p_to_stars <- function(p) {
  dplyr::case_when(
    !is.finite(p) ~ "NA",
    p < 0.0001 ~ "****",
    p < 0.001 ~ "***",
    p < 0.01 ~ "**",
    p < 0.05 ~ "*",
    TRUE ~ "ns"
  )
}

compact_letters <- function(posthoc, groups, alpha = 0.05) {
  if (nrow(posthoc)==0 || length(groups)<2) return(tibble::tibble(.group=groups,cld=NA_character_))
  safe <- stats::setNames(paste0("G",seq_along(groups)),groups)
  pvec <- posthoc$p_adjusted
  names(pvec) <- paste(unname(safe[posthoc$group1]),unname(safe[posthoc$group2]),sep="-")
  letters <- tryCatch(multcompView::multcompLetters(pvec,threshold=alpha)$Letters,error=function(e) NULL)
  if(is.null(letters)) return(tibble::tibble(.group=groups,cld=NA_character_))
  tibble::tibble(.group=groups,cld=unname(letters[unname(safe[groups])]))
}
add_pairwise_annotations <- function(plot, data, posthoc, mode, hide_ns,
                                     horizontal = FALSE, x_label = NULL, y_label = NULL) {
  if (mode == "None" || nrow(posthoc) == 0) return(plot)
  groups <- levels(droplevels(data$.group))

  if (mode == "Compact letters") {
    letter_data <- compact_letters(posthoc, groups)
    if (horizontal) {
      x_max <- max(data$.outcome, na.rm = TRUE)
      x_min <- min(data$.outcome, na.rm = TRUE)
      span <- max(x_max - x_min, .Machine$double.eps)
      letter_data$x <- x_max + 0.08 * span
      letter_data$y <- match(letter_data$.group, groups)
      return(plot +
        ggplot2::geom_text(
          data = letter_data,
          ggplot2::aes(x = x, y = y, label = cld),
          inherit.aes = FALSE, fontface = "bold", size = 5
        ) +
        ggplot2::coord_cartesian(clip = "off") +
        ggplot2::theme(plot.margin = ggplot2::margin(10, 32, 10, 10)))
    }
    y_max <- max(data$.outcome, na.rm = TRUE)
    y_min <- min(data$.outcome, na.rm = TRUE)
    span <- max(y_max - y_min, .Machine$double.eps)
    letter_data$x <- match(letter_data$.group, groups)
    letter_data$y <- y_max + 0.025 * span
    return(plot +
      ggplot2::geom_text(
        data = letter_data,
        ggplot2::aes(x = x, y = y, label = cld),
        inherit.aes = FALSE, fontface = "bold", size = 5
      ) +
      ggplot2::coord_cartesian(clip = "off") +
      ggplot2::theme(plot.margin = ggplot2::margin(10, 14, 10, 10)))
  }

  ann <- posthoc |>
    dplyr::mutate(
      stars = p_to_stars(p_adjusted),
      label = if (mode == "Adjusted p-values") {
        paste0("p = ", ifelse(p_adjusted < 0.001, "<0.001", sprintf("%.3f", p_adjusted)))
      } else stars
    )
  if (isTRUE(hide_ns)) ann <- ann |> dplyr::filter(stars != "ns")
  if (nrow(ann) == 0) return(plot)

  ann <- ann |>
    dplyr::mutate(
      x1 = match(group1, groups),
      x2 = match(group2, groups),
      bracket_span = abs(x2 - x1)
    ) |>
    dplyr::arrange(bracket_span, p_adjusted, x1, x2) |>
    dplyr::mutate(layer = dplyr::row_number())

  if (horizontal) {
    x_max <- max(data$.outcome, na.rm = TRUE)
    x_min <- min(data$.outcome, na.rm = TRUE)
    span <- max(x_max - x_min, .Machine$double.eps)
    ann <- ann |>
      dplyr::mutate(
        xpos = x_max + (0.05 + 0.11 * layer) * span,
        tick = 0.020 * span,
        ymid = (x1 + x2) / 2
      )
    return(plot +
      ggplot2::geom_segment(data = ann, ggplot2::aes(x=xpos, xend=xpos, y=x1, yend=x2), inherit.aes=FALSE) +
      ggplot2::geom_segment(data = ann, ggplot2::aes(x=xpos-tick, xend=xpos, y=x1, yend=x1), inherit.aes=FALSE) +
      ggplot2::geom_segment(data = ann, ggplot2::aes(x=xpos-tick, xend=xpos, y=x2, yend=x2), inherit.aes=FALSE) +
      ggplot2::geom_text(data = ann, ggplot2::aes(x=xpos+1.8*tick, y=ymid, label=label), inherit.aes=FALSE, hjust=0, size=3.8) +
      ggplot2::coord_cartesian(clip = "off") +
      ggplot2::theme(plot.margin = ggplot2::margin(10, 55, 10, 10)))
  }

  y_max <- max(data$.outcome, na.rm = TRUE)
  y_min <- min(data$.outcome, na.rm = TRUE)
  span <- max(y_max - y_min, .Machine$double.eps)
  ann <- ann |>
    dplyr::mutate(
      ypos = y_max + (0.035 + 0.095 * layer) * span,
      tick = 0.018 * span,
      xmid = (x1 + x2) / 2
    )
  plot +
    ggplot2::geom_segment(data=ann, ggplot2::aes(x=x1, xend=x2, y=ypos, yend=ypos), inherit.aes=FALSE) +
    ggplot2::geom_segment(data=ann, ggplot2::aes(x=x1, xend=x1, y=ypos, yend=ypos-tick), inherit.aes=FALSE) +
    ggplot2::geom_segment(data=ann, ggplot2::aes(x=x2, xend=x2, y=ypos, yend=ypos-tick), inherit.aes=FALSE) +
    ggplot2::geom_text(data=ann, ggplot2::aes(x=xmid, y=ypos+1.5*tick, label=label), inherit.aes=FALSE, vjust=0, size=3.8) +
    ggplot2::scale_y_continuous(expand = ggplot2::expansion(mult = c(0.05, 0.10))) +
    ggplot2::coord_cartesian(clip = "off") +
    ggplot2::theme(plot.margin = ggplot2::margin(10, 14, 10, 10))
}

