cliff_delta_help <- "Cliff's delta compares every observation in the first named group with every observation in the second named group. It is the share of pairs where the first group is higher, minus the share where it is lower. 0 means neither group tends to be higher. 1 means every value in the first group is higher. -1 means every value is lower. The number has no units, so a lesion score and a body weight can both be read as effect sizes. For postmortem scores that are mostly 0, this is the effect to read. A positive value means the first named group tends to have the higher score."

hodges_lehmann_help <- "The Hodges-Lehmann difference is the median of all pairwise differences, first named group minus second named group, in the units of the measurement. A value of 40 g means the typical animal in the first group is 40 g heavier. The 95% interval is the Wilcoxon confidence interval for that median difference. On integer scores such as lesion scores, most pairs are 0 minus 0, so the median difference and its interval are often 0 even when one group tends to score higher. That 0 is the median of the paired differences. Cliff's delta still shows the direction and size of that tendency."

build_adjusted_model <- function(data, outcome, group, covariates,
                                 interactions = character(),
                                 random_effect, model_type,
                                 center_numeric = TRUE) {
  vars <- unique(c(outcome, group, covariates, random_effect))
  vars <- vars[nzchar(vars)]
  model_data <- data |>
    dplyr::select(dplyr::all_of(vars)) |>
    tidyr::drop_na()

  retained_group_levels <- levels(data[[group]])
  retained_group_levels <- retained_group_levels[retained_group_levels %in% unique(as.character(model_data[[group]]))]
  model_data[[group]] <- factor(as.character(model_data[[group]]), levels=retained_group_levels)
  stats::contrasts(model_data[[group]]) <- stats::contr.treatment(length(retained_group_levels), base=1)
  if (length(random_effect)) for (v in random_effect) model_data[[v]] <- factor(model_data[[v]])

  if (isTRUE(center_numeric) && length(covariates)) {
    numeric_covariates <- covariates[vapply(model_data[covariates], is.numeric, logical(1))]
    for (v in numeric_covariates) {
      model_data[[v]] <- as.numeric(scale(model_data[[v]], center = TRUE, scale = FALSE))
    }
  }

  fixed_terms <- unique(c(group, covariates))
  interaction_terms <- unique(interactions[nzchar(interactions)])
  formula_terms <- c(fixed_terms, interaction_terms)
  fixed_formula <- paste(outcome, "~", paste(formula_terms, collapse = " + "))
  mixed_formula <- if (length(random_effect)) {
    paste(fixed_formula, "+", paste0("(1 | ", random_effect, ")", collapse=" + "))
  } else fixed_formula

  fit <- switch(
    model_type,
    "Linear model (LM)" = stats::lm(stats::as.formula(fixed_formula), data = model_data),
    "Logistic model (GLM)" = stats::glm(stats::as.formula(fixed_formula), family = stats::binomial(), data = model_data),
    "Poisson model (GLM)" = stats::glm(stats::as.formula(fixed_formula), family = stats::poisson(), data = model_data),
    "Linear mixed model (LMM)" = lme4::lmer(stats::as.formula(mixed_formula), data = model_data, REML = TRUE),
    "Logistic mixed model (GLMM)" = lme4::glmer(
      stats::as.formula(mixed_formula), family = stats::binomial(), data = model_data,
      control = lme4::glmerControl(optimizer = "bobyqa", optCtrl = list(maxfun = 100000))
    ),
    "Poisson mixed model (GLMM)" = lme4::glmer(
      stats::as.formula(mixed_formula), family = stats::poisson(), data = model_data,
      control = lme4::glmerControl(optimizer = "bobyqa", optCtrl = list(maxfun = 100000))
    )
  )

  list(
    fit = fit,
    data = model_data,
    formula = if (model_type %in% c("Linear mixed model (LMM)", "Logistic mixed model (GLMM)", "Poisson mixed model (GLMM)")) mixed_formula else fixed_formula,
    group = group,
    outcome = outcome,
    covariates = covariates,
    interactions = interaction_terms,
    random_effect = random_effect,
    model_type = model_type
  )
}

model_coefficient_table <- function(model_object) {
  fit <- model_object$fit
  exponentiate <- model_object$model_type %in% c(
    "Logistic model (GLM)", "Poisson model (GLM)",
    "Logistic mixed model (GLMM)", "Poisson mixed model (GLMM)"
  )

  out <- broom.mixed::tidy(
    fit, effects = "fixed", conf.int = TRUE, exponentiate = exponentiate
  )

  # broom/broom.mixed columns differ by model class and package version.
  # Build each output column explicitly instead of assuming p.value exists.
  n <- nrow(out)
  get_col <- function(candidates, default = rep(NA_real_, n)) {
    hit <- candidates[candidates %in% names(out)]
    if (length(hit)) out[[hit[1]]] else default
  }

  estimate <- get_col(c("estimate"))
  std_error <- get_col(c("std.error", "SE"))
  statistic <- get_col(c("statistic", "z.value", "t.value", "z.ratio", "t.ratio"))
  p_value <- get_col(c("p.value", "p_value", "Pr(>|z|)", "Pr(>|t|)"))
  conf_low <- get_col(c("conf.low", "lower.CL", "asymp.LCL"))
  conf_high <- get_col(c("conf.high", "upper.CL", "asymp.UCL"))

  # If the tidier omitted p-values, derive a documented approximation.
  p_source <- if (any(is.finite(p_value))) {
    "Reported by broom.mixed/model summary"
  } else if (any(is.finite(statistic))) {
    p_value <- 2 * stats::pnorm(abs(statistic), lower.tail = FALSE)
    "Approximate two-sided normal test derived from the reported statistic"
  } else if (any(is.finite(estimate)) && any(is.finite(std_error))) {
    statistic <- estimate / std_error
    p_value <- 2 * stats::pnorm(abs(statistic), lower.tail = FALSE)
    "Approximate two-sided normal test derived from estimate / SE"
  } else {
    "Not available for this fitted model"
  }

  tibble::tibble(
    Term = as.character(get_col(c("term"), rep("", n))),
    Estimate = estimate,
    `Standard error` = std_error,
    Statistic = statistic,
    `95% CI lower` = conf_low,
    `95% CI upper` = conf_high,
    `P value` = p_value,
    `P-value source` = p_source,
    Scale = if (exponentiate) "Ratio scale (OR or rate ratio)" else "Outcome scale"
  )
}

model_random_table <- function(model_object, calculate_ci = FALSE) {
 fit<-model_object$fit
 if(!inherits(fit,"merMod")) return(tibble::tibble(Component="No random effect",Variance=NA_real_,SD=NA_real_,`SD 95% CI lower`=NA_real_,`SD 95% CI upper`=NA_real_))
 out<-as.data.frame(lme4::VarCorr(fit)) |> dplyr::transmute(Component=dplyr::case_when(grp=="Residual"~"Residual",is.na(var2)~paste0("Random intercept: ",grp),TRUE~paste0("Correlation: ",grp)),Variance=vcov,SD=sdcor,`SD 95% CI lower`=NA_real_,`SD 95% CI upper`=NA_real_)
 if(isTRUE(calculate_ci)){ci<-tryCatch(suppressMessages(stats::confint(fit,parm="theta_",method="profile",oldNames=FALSE)),error=function(e)NULL);if(!is.null(ci)){k<-min(nrow(out),nrow(ci));out$`SD 95% CI lower`[seq_len(k)]<-ci[seq_len(k),1];out$`SD 95% CI upper`[seq_len(k)]<-ci[seq_len(k),2]}}
 out
}

random_effect_interpretation <- function(model_object) {
  fit <- model_object$fit
  if (!inherits(fit, "merMod")) {
    return("No random-effect interpretation is available because the fitted model is an LM/GLM without a random effect.")
  }
  vc <- as.data.frame(lme4::VarCorr(fit))
  intercept_row <- vc[is.na(vc$var2) & vc$var1 == "(Intercept)" & vc$grp != "Residual", , drop = FALSE]
  if (!nrow(intercept_row)) {
    return("No random-intercept standard deviation was found in this fitted model.")
  }
  sd_value <- intercept_row$sdcor[1]
  variance_value <- intercept_row$vcov[1]
  group_name <- intercept_row$grp[1]
  paste0(
    "sd__(Intercept) is the estimated standard deviation of cluster-specific intercepts for ",
    group_name, ". Here it is ", sprintf("%.3f", sd_value),
    ", corresponding to a variance of ", sprintf("%.3f", variance_value),
    ". It describes how much the expected baseline outcome varies between ", group_name,
    " levels after accounting for the fixed effects. A value near zero means the fitted model found little additional between-cluster variation; it does not measure bird-to-bird residual variation."
  )
}




cfu_candidate_columns <- function(data) {
  nm <- names(data)
  detected <- nm[grepl("(^|_)(cfu_detected|cfu_detection|culture_positive|culture_detected)(_|$)",nm,ignore.case=TRUE)]
  burden <- nm[grepl("cfu",nm,ignore.case=TRUE) & vapply(data,is.numeric,logical(1))]
  burden <- burden[!grepl("log|detected|detection|positive|binary",burden,ignore.case=TRUE)]
  log_burden <- nm[grepl("cfu",nm,ignore.case=TRUE) & grepl("log",nm,ignore.case=TRUE) & vapply(data,is.numeric,logical(1))]
  list(detected=detected,burden=burden,log_burden=log_burden)
}
choose_cfu_burden <- function(data) {
  z <- cfu_candidate_columns(data)
  preferred <- z$burden[grepl("per_g|gram|count|burden",z$burden,ignore.case=TRUE)]
  (preferred[1] %||% z$burden[1] %||% z$log_burden[1])
}
choose_cfu_detection <- function(data) {
  z <- cfu_candidate_columns(data)
  z$detected[1] %||% choose_cfu_burden(data)
}
binary_event_from_values <- function(x) {
  if(is.numeric(x)) return(as.integer(x > 0))
  y <- tolower(trimws(as.character(x)))
  positive <- c("yes","y","true","1","positive","pos","detected","present")
  negative <- c("no","n","false","0","negative","neg","not detected","absent")
  out <- ifelse(y %in% positive,1L,ifelse(y %in% negative,0L,NA_integer_))
  out
}

postmortem_candidate_columns <- function(data) {
  nm <- names(data)
  is_score <- grepl("peritone|liver|airsac|lung|heart|spleen|lesion|postmortem|petech|congestion|exudate|inflammation|transparency|score", nm, ignore.case=TRUE)
  exclude <- grepl("original|weight|ratio|cfu|clinical|animal|random|pen|box|treatment|haplotype", nm, ignore.case=TRUE)
  nm[is_score & vapply(data,is.numeric,logical(1)) & !exclude]
}
postmortem_tissue <- function(x) {
  dplyr::case_when(
    grepl("peritone",x,ignore.case=TRUE) ~ "Peritoneum",
    grepl("liver",x,ignore.case=TRUE) ~ "Liver",
    grepl("airsac",x,ignore.case=TRUE) ~ "Airsac",
    grepl("lung|congestion",x,ignore.case=TRUE) ~ "Lung",
    grepl("heart|petech",x,ignore.case=TRUE) ~ "Heart",
    grepl("spleen",x,ignore.case=TRUE) ~ "Spleen",
    grepl("total|lesion|postmortem",x,ignore.case=TRUE) ~ "Overall",
    TRUE ~ "Other")
}
postmortem_forest_results <- function(data, group, outcomes, reference, adjust_method="holm") {
  lev <- unique(as.character(stats::na.omit(data[[group]])))
  if(!reference %in% lev) reference <- lev[1]
  comparisons <- setdiff(lev,reference)
  purrr::map_dfr(outcomes,function(outcome){
    y <- suppressWarnings(as.numeric(data[[outcome]])); event <- is.finite(y) & y > 0
    purrr::map_dfr(comparisons,function(g){
      keep <- !is.na(data[[group]]) & as.character(data[[group]]) %in% c(reference,g) & is.finite(y)
      gg <- factor(as.character(data[[group]][keep]),levels=c(reference,g)); yy <- event[keep]
      a<-sum(gg==g & yy);b<-sum(gg==g & !yy);c<-sum(gg==reference & yy);d<-sum(gg==reference & !yy)
      correction<-any(c(a,b,c,d)==0);aa<-a+.5*correction;bb<-b+.5*correction;cc<-c+.5*correction;dd<-d+.5*correction
      lor<-log((aa*dd)/(bb*cc));se<-sqrt(1/aa+1/bb+1/cc+1/dd);fit<-tryCatch(stats::fisher.test(table(gg,yy)),error=function(e)NULL)
      tibble::tibble(Tissue=postmortem_tissue(outcome),Outcome=outcome,Comparison=paste(g,"vs",reference),Events_reference=c,Total_reference=c+d,Events_comparison=a,Total_comparison=a+b,OR=exp(lor),Lower=exp(lor-1.96*se),Upper=exp(lor+1.96*se),p_raw=if(is.null(fit))NA_real_ else fit$p.value,Zero_cell_correction=correction)
    })
  }) |> dplyr::mutate(p_adjusted=stats::p.adjust(p_raw,method=adjust_method),`Adjusted P`=fmt_p(p_adjusted))
}

