prepare_mv_matrix <- function(data, vars, scale_values=TRUE) {
  vars <- intersect(vars, names(data)); shiny::validate(shiny::need(length(vars)>=2,"Select at least two numeric variables."))
  x <- data[,vars,drop=FALSE]; shiny::validate(shiny::need(all(vapply(x,is.numeric,logical(1))),"PCA/MDS variables must be numeric."))
  for(nm in names(x)){m<-median(x[[nm]],na.rm=TRUE);shiny::validate(shiny::need(is.finite(m),paste("No usable values:",nm)));x[[nm]][!is.finite(x[[nm]])]<-m}
  x<-x[,vapply(x,function(z)sd(z)>0,logical(1)),drop=FALSE];shiny::validate(shiny::need(ncol(x)>=2,"At least two variables need non-zero variance."))
  m<-as.matrix(x);if(scale_values)m<-scale(m);m
}
auc_value <- function(y,p){n1<-sum(y==1);n0<-sum(y==0);if(!n1||!n0)return(NA_real_);(sum(rank(p)[y==1])-n1*(n1+1)/2)/(n1*n0)}
class_metrics <- function(y,p,cut=.5){pr<-as.integer(p>=cut);tp<-sum(pr==1&y==1);tn<-sum(pr==0&y==0);fp<-sum(pr==1&y==0);fn<-sum(pr==0&y==1);tibble::tibble(Accuracy=(tp+tn)/length(y),Sensitivity=tp/max(1,tp+fn),Specificity=tn/max(1,tn+fp),AUC=auc_value(y,p),TP=tp,FP=fp,TN=tn,FN=fn)}
roc_data <- function(y,p){th<-sort(unique(c(Inf,p,-Inf)),decreasing=TRUE);purrr::map_dfr(th,function(t){pr<-as.integer(p>=t);tp<-sum(pr==1&y==1);tn<-sum(pr==0&y==0);fp<-sum(pr==1&y==0);fn<-sum(pr==0&y==1);tibble::tibble(FPR=1-tn/max(1,tn+fp),TPR=tp/max(1,tp+fn))})}
fit_browser_forest <- function(data, formula, ntree=100, mtry=NULL, seed=1){
 set.seed(seed);mf<-model.frame(formula,data=data,na.action=na.omit);y<-model.response(mf);vars<-attr(terms(formula),"term.labels");if(is.null(mtry)||mtry<1)mtry<-max(1,floor(sqrt(length(vars))));trees<-vector("list",ntree);oob<-vector("list",ntree);imp<-setNames(rep(0,length(vars)),vars)
 for(i in seq_len(ntree)){idx<-sample.int(nrow(mf),nrow(mf),TRUE);hold<-setdiff(seq_len(nrow(mf)),unique(idx));use<-sample(vars,min(mtry,length(vars)));f<-reformulate(use,response=names(mf)[1]);tr<-rpart::rpart(f,mf[idx,,drop=FALSE],method="class",control=rpart::rpart.control(cp=.005,minsplit=10,xval=0));trees[[i]]<-tr;vi<-tr$variable.importance;if(length(vi))imp[names(vi)]<-imp[names(vi)]+vi;if(length(hold)){pp<-predict(tr,mf[hold,,drop=FALSE],type="prob");oob[[i]]<-tibble::tibble(row=hold,p=pp[,ncol(pp)])}}
 oo<-bind_rows(oob)|>group_by(row)|>summarise(p=mean(p),.groups="drop");list(trees=trees,importance=sort(imp/ntree,decreasing=TRUE),oob=oo,y=as.integer(y[oo$row]==levels(y)[2]),levels=levels(y),ntree=ntree,mtry=mtry)
}

