make_example_data <- function(seed = 20261103L) {
  set.seed(seed); n <- 72L
  treatment <- factor(rep(c("Unvaccinated", "Intramuscular", "Drinking water"), each=24), levels=c("Unvaccinated","Intramuscular","Drinking water"))
  box <- factor(rep(sprintf("Box-%02d",1:12), each=6)); sex <- factor(rep(c("F","M"),length.out=n)); farm <- factor(rep(c("Farm North","Farm South","Farm West"),each=24))
  age_days <- sample(28:36,n,TRUE); baseline_weight_g <- round(rnorm(n,1120+35*(sex=="M"),105))
  te <- c("Unvaccinated"=0,"Intramuscular"=-0.65,"Drinking water"=-0.95)[as.character(treatment)]; be <- rep(rnorm(12,0,.20),each=6)
  biomarker_1 <- round(rnorm(n,.3-te*.25,.72),3); biomarker_2 <- round(.5*biomarker_1+rnorm(n,0,.65),3); biomarker_3 <- round(rnorm(n,.25*(sex=="M"),.8),3)
  biomarker_4 <- round(.35*biomarker_2-.2*biomarker_3+rnorm(n,0,.66),3); biomarker_5 <- round(rnorm(n,0,.85),3)
  risk <- .75+te+be+.4*biomarker_1-.18*biomarker_4; disease_detected <- factor(rbinom(n,1,plogis(risk)),levels=c(0,1),labels=c("No","Yes"))
  logcfu <- pmax(0,3.3+1.15*(disease_detected=="Yes")+te+be+rnorm(n,0,.72)); cfu_per_g <- ifelse(runif(n)<.22+.28*(disease_detected=="No"),0,round(10^logcfu))
  lesion_score <- pmin(4L,rpois(n,pmax(.05,.45+1.25*(disease_detected=="Yes")+.25*(treatment=="Unvaccinated"))))
  final_weight_g <- round(baseline_weight_g+rnorm(n,410-55*(disease_detected=="Yes"),75)); biomarker_5[sample(seq_len(n),5)] <- NA_real_
  tibble::tibble(animal_id=sprintf("VET-%03d",seq_len(n)),treatment,box,farm,sex,age_days,baseline_weight_g,final_weight_g,disease_detected,cfu_per_g,lesion_score,biomarker_1,biomarker_2,biomarker_3,biomarker_4,biomarker_5)
}
