valid_grouping_columns <- function(data) {
  n <- nrow(data)
  nm <- names(data)
  distinct_n <- vapply(data,dplyr::n_distinct,integer(1),na.rm=TRUE)
  categorical <- vapply(data,function(z)is.factor(z)||is.character(z)||is.logical(z)||is.integer(z),logical(1))
  id_like_name <- grepl("(^|_)(id|animal_id|bird_id|random_id|wingtag|tag|sample_id|row|index|number|no)(_|$)",nm,ignore.case=TRUE)
  nearly_unique <- distinct_n >= max(20,floor(.50*n))
  nm[categorical & distinct_n>=2 & distinct_n<=min(20,max(2,floor(.25*n))) & !id_like_name & !nearly_unique]
}
choose_grouping_column <- function(data, current=NULL) {
  candidates <- valid_grouping_columns(data)
  if(!length(candidates)) return(NULL)
  score <- rep(0,length(candidates)); names(score)<-candidates
  exact_preferences <- c("treatment","treatment_group","group","experimental_group","study_group","arm","study_arm","intervention","vaccination","vaccine_group","administration_route","route")
  lower <- tolower(candidates)
  for(i in seq_along(exact_preferences)) score[lower==exact_preferences[i]] <- score[lower==exact_preferences[i]] + (200-i)
  score <- score + 120*grepl("treat|intervention|vaccin|administration|route",candidates,ignore.case=TRUE)
  score <- score + 90*grepl("(^|_)group($|_)|(^|_)arm($|_)",candidates,ignore.case=TRUE)
  score <- score + 20*grepl("haplotype|genotype|sex|farm|site|batch|pen|room|box",candidates,ignore.case=TRUE)
  score <- score - 100*grepl("id|tag|random|sample|clinical|score|outcome|detected",candidates,ignore.case=TRUE)
  if(!is.null(current)&&current%in%candidates)score[current]<-score[current]+5
  candidates[which.max(score)]
}
ordered_group_levels <- function(x) {
  lev <- unique(as.character(stats::na.omit(x)))
  preferred <- c("Control","control","Unvaccinated","Unvacc","PBS","Placebo","Sham")
  ref <- preferred[preferred %in% lev][1]
  if(length(ref)) c(ref,setdiff(lev,ref)) else lev
}


package_versions_text <- function() {
  pkgs <- intersect(required_packages, rownames(installed.packages()))
  versions <- vapply(pkgs,function(x) as.character(utils::packageVersion(x)),character(1))
  c(
    paste0("R version: ",R.version.string),
    paste0("Platform: ",R.version$platform),
    "Package versions:",
