  )
}
strategy_specification <- function(strategy, group=NULL, outcome=NULL, adjustment="holm", reference=NULL) {
  header <- paste0("Strategy: ",strategy)
  common <- c(header,paste0("Grouping variable: ",group %||% "not selected"),paste0("Outcome: ",outcome %||% "not selected"))
  details <- switch(strategy,
    manual=c("User-selected outcome handling, test, plot, and optional adjusted model."),
    cfu_detection=c("Question: was CFU detected?","Endpoint: explicit Yes/No detection column, or numeric CFU converted to >0 versus 0.","Analysis: Fisher exact test; pairwise Fisher tests when needed.","Effect: event proportions and odds ratios with confidence intervals."),
    cfu_full=c("Question: does the complete CFU burden distribution differ, including zeros?","Endpoint: original numeric CFU burden with all zero and positive observations retained.","Analysis: Mann-Whitney-Wilcoxon for 2 groups or Kruskal-Wallis plus Dunn for 3+ groups.","Interpretation combines failure to detect CFU and burden among positive animals."),
    cfu_positive=c("Question: among CFU-positive animals, does burden differ?","Endpoint: animals with numeric CFU >0 only; raw burden is displayed as log10(CFU) unless the uploaded outcome is already logged.","Analysis: Mann-Whitney-Wilcoxon for 2 groups or Kruskal-Wallis plus Dunn for 3+ groups.","This strategy does not test differences in the proportion CFU-positive."),
    pm_incidence=c("Question: did each animal have any postmortem lesion?","Endpoint: one overall postmortem score converted to absent (=0) or present (>0).",paste0("Reference group: ",reference %||% "first ordered group"),"Analysis: Fisher exact tests and odds ratios for the overall binary endpoint.",paste0("Multiplicity adjustment: ",adjustment,".")),
    pm_positive=c("Question: among affected animals, were postmortem scores more severe?","Endpoint: selected overall postmortem score after excluding values of 0.","Analysis: Mann-Whitney-Wilcoxon for 2 groups or Kruskal-Wallis plus Dunn for 3+ groups.",paste0("Multiplicity adjustment for pairwise tests: ",adjustment,".")),
    pm_full=c("Question: which specific tissues showed lesions?","Endpoint: every selected tissue score converted separately to absent (=0) or present (>0).",paste0("Reference group: ",reference %||% "first ordered group"),"Analysis: one Fisher exact test and odds ratio per tissue/group comparison.",paste0("Multiplicity adjustment across the tissue profile: ",adjustment,".")),
    categorical=c("Endpoint: distribution of a categorical outcome across groups.","Overall comparison: chi-square when expected counts are adequate; Fisher exact when expected counts are small.","Plot: within-group stacked percentages."),
    c("No preset strategy description is available.")
  )
  c(common,details)
}
