}

draw_classification_tree <- function(fit, main="Classification decision tree") {
  if (requireNamespace("rpart.plot", quietly=TRUE)) {
    ok <- tryCatch({
      rpart.plot::rpart.plot(fit,type=3,extra=104,fallen.leaves=TRUE,branch=1,yesno=2,box.palette="GnBu",shadow.col="gray85",roundint=FALSE,nn=TRUE,tweak=1.05,main=main)
      TRUE
    }, error=function(e) FALSE)
    if (isTRUE(ok)) return(invisible(TRUE))
  }
  graphics::par(mar=c(2,2,4,2),xpd=NA)
  graphics::plot(fit,uniform=TRUE,margin=.20,compress=FALSE,branch=.45)
  graphics::text(fit,use.n=TRUE,all=TRUE,cex=.95)
  graphics::title(main=main,sub="Left branch = Yes/condition true; right branch = No/condition false",cex.sub=.8)
  invisible(FALSE)
}

