    shiny::tagList(
      shiny::selectizeInput("group_level_order", field_label("Included groups and order", "Only selected groups are analysed. The first level is the LM/GLM/LMM/GLMM reference. Press x to exclude a level."), choices=observed, selected=selected, multiple=TRUE, options=list(plugins=list("remove_button"), persist=FALSE)),
      shiny::uiOutput("group_reference_status")
    )
  })
  shiny::observeEvent(input$group_level_order, {
    lev <- input$group_level_order %||% character()
    if(length(lev) >= 2) group_order_memory(lev)
  }, ignoreInit=FALSE)
  output$group_reference_status <- shiny::renderUI({
    lev <- group_order_memory()
    if(length(lev)<2) return(shiny::div(class="text-danger small","Select at least two groups."))
    shiny::div(class="small text-muted", shiny::tags$b("Reference/control: "),lev[1],shiny::tags$br(),paste("Included order:",paste(lev,collapse=" > ")))
  })

  shiny::observeEvent(input$strategy, {
    d<-raw_data();if(is.null(d))return();nm<-names(d)
    if(input$strategy=="manual"){
      numeric_cols<-nm[vapply(d,is.numeric,logical(1))];group_cols<-valid_grouping_columns(d);preferred_group<-choose_grouping_column(d,input$group)
      shiny::updateSelectInput(session,"group",choices=group_cols,selected=preferred_group);shiny::updateSelectInput(session,"outcome",selected=numeric_cols[1] %||% nm[1]);shiny::updateSelectInput(session,"outcome_type",selected="Numeric");shiny::updateSelectInput(session,"transformation",selected="None");shiny::updateSelectInput(session,"global_test",selected="Auto");shiny::updateSelectInput(session,"posthoc_test",selected="Auto");shiny::updateSelectInput(session,"plot_type",selected="Raincloud / half-eye");shiny::updateCheckboxInput(session,"enable_model",value=FALSE);group_order_memory(character());shiny::showNotification("Manual mode reset to defaults.");return()
    }
