        shiny::updateSelectInput(session,"transformation",selected="None")
        shiny::updateSelectInput(session,"global_test",selected="Kruskal-Wallis")
        shiny::updateSelectInput(session,"posthoc_test",selected="Dunn test")
        shiny::updateSelectInput(session,"plot_type",selected="Boxplot + observations")
      }
      shiny::updateSelectInput(session,"adjust_method",selected="holm")
      shiny::showNotification(paste("CFU strategy grouped by",preferred_group %||% "the selected grouping variable","using",chosen %||% "the selected outcome"),type="message")
    }
    if(input$strategy %in% c("pm_incidence","pm_positive","pm_full")){
      preferred_group<-choose_grouping_column(d,input$group)
      if(!is.null(preferred_group)){
        lev<-ordered_group_levels(d[[preferred_group]])
        shiny::freezeReactiveValue(input,"group")
        shiny::updateSelectInput(session,"group",choices=valid_grouping_columns(d),selected=preferred_group)
        group_order_memory(lev)
        shiny::updateSelectInput(session,"pm_reference",choices=lev,selected=lev[1])
        shiny::updateSelectInput(session,"control_group",choices=lev,selected=lev[1])
      }
      vars<-postmortem_candidate_columns(d)
      overall<-vars[grepl("postmortem.*total|lesion.*total|total.*score|overall",vars,ignore.case=TRUE)][1] %||% vars[1]
      if(!is.null(overall)) shiny::updateSelectInput(session,"outcome",selected=overall)
      if(input$strategy=="pm_full"){
        shiny::updateSelectizeInput(session,"pm_variables",choices=vars,selected=vars,server=TRUE)
        shiny::updateSelectInput(session,"pm_focus",selected="All tissues")
        shiny::updateSelectInput(session,"plot_type",selected="Postmortem odds-ratio forest")
      } else if(input$strategy=="pm_incidence"){
        shiny::updateSelectInput(session,"outcome_type",selected="Binary")
        shiny::updateSelectInput(session,"global_test",selected="Fisher exact")
        shiny::updateSelectInput(session,"posthoc_test",selected="Fisher exact")
        shiny::updateSelectInput(session,"plot_type",selected="Detection proportions")
      } else {
