    observed<-ordered_group_levels(d[[input$group]]);ordered<-group_order_memory();lev<-c(ordered[ordered%in%observed],setdiff(observed,ordered));if(!length(lev))return()
    current<-isolate(input$pm_reference);selected<-if(!is.null(current)&&current%in%lev)current else lev[1]
    shiny::updateSelectInput(session,"pm_reference",choices=lev,selected=selected)
  })
  effective_transformation <- shiny::reactive({
    if(input$strategy=="cfu_positive") return(if(grepl("log",input$outcome %||% "",ignore.case=TRUE)) "Already logged CFU column" else "Automatic log10(x) for positive CFU")
    if(input$strategy %in% c("cfu_detection","pm_incidence","pm_full")) return("Not applicable: binary endpoint")
    input$transformation %||% "None"
  })

  transformation_qc <- shiny::reactive({
    d<-raw_data();shiny::req(d,input$outcome,input$outcome %in% names(d))
    x<-d[[input$outcome]];xn<-if(is.numeric(x))as.numeric(x)else suppressWarnings(as.numeric(x));tr<-effective_transformation();off<-input$offset %||% 1
    invalid<-if(is.numeric(x)&&identical(tr,"Square root"))sum(xn<0,na.rm=TRUE)else if(is.numeric(x)&&tr%in%c("log10(x + offset)","ln(x + offset)"))sum(xn+off<=0,na.rm=TRUE)else 0L
    transformed<-tryCatch({if(tr=="Automatic log10(x) for positive CFU")log10(xn[xn>0])else if(tr%in%c("Not applicable: binary endpoint","Already logged CFU column"))xn else transform_outcome(xn,tr,off)},error=function(e)rep(NA_real_,length(xn)))
    tibble::tibble(Scale=tr,Rows=length(x),Missing=sum(is.na(x)),Invalid=invalid,Offset=if(tr%in%c("log10(x + offset)","ln(x + offset)"))off else NA_real_,`Original mean`=if(any(is.finite(xn)))mean(xn,na.rm=TRUE)else NA_real_,`Analysis-scale mean`=if(any(is.finite(transformed)))mean(transformed,na.rm=TRUE)else NA_real_,`Original range`=if(any(is.finite(xn)))paste(signif(range(xn,na.rm=TRUE),5),collapse=" to ")else NA_character_,`Analysis-scale range`=if(any(is.finite(transformed)))paste(signif(range(transformed,na.rm=TRUE),5),collapse=" to ")else NA_character_)
  })
  output$transformation_status <- shiny::renderUI({
    q<-transformation_qc();tr<-q$Scale[1]
    preset<-input$strategy %in% c("cfu_positive","cfu_detection","pm_incidence","pm_full")
    cls<-if(q$Invalid[1]>0)"alert alert-warning"else"small text-muted border rounded p-2 mb-2"
    shiny::div(class=cls,shiny::tags$b("Analysis scale: "),tr,
      if(is.finite(q$Offset[1]))paste0("; offset = ",q$Offset[1])else"",
      paste0(". Rows: ",q$Rows[1],"; missing: ",q$Missing[1],"; invalid: ",q$Invalid[1],". Original range ",q$`Original range`[1],"; analysis-scale range ",q$`Analysis-scale range`[1],"."),
      if(preset)" This preset controls the scale shown here."else" The selected transformation is applied before plotting and analysis.")
  })

  output$transformation_inference_note <- shiny::renderUI({
    if(input$strategy=="pm_full")return(NULL)
    tr<-effective_transformation();global<-tryCatch(selected_global_test(),error=function(e)"");posthoc<-tryCatch(selected_posthoc_test(),error=function(e)"")
    rank_based<-global%in%c("Kruskal-Wallis","Mann-Whitney-Wilcoxon")||posthoc%in%c("Dunn test","Mann-Whitney-Wilcoxon")
    monotonic<-tr%in%c("log10(x + offset)","ln(x + offset)","Square root","Automatic log10(x) for positive CFU")
    if(rank_based&&monotonic)return(shiny::div(class="alert alert-info py-2 px-3 small",shiny::tags$b("Why the P values did not change: "),"Kruskal-Wallis, Mann-Whitney, and Dunn use ranks. A valid monotonic transformation preserves observation order, so their statistics and P values are expected to remain identical. The plot, means, SDs, axis units, and LM/LMM estimates do change."))
    if(tr!="None"&&!grepl("Not applicable",tr))return(shiny::div(class="alert alert-success py-2 px-3 small",shiny::tags$b("Transformation applied: "),paste0("Plots, summaries, tests, and enabled adjusted models use the ",tr," scale. Parametric estimates and P values may change.")))
    NULL
  })

  analysis_data <- shiny::reactive({
    x <- raw_data()
    shiny::req(x, input$group, input$outcome)

    out <- x |>
      dplyr::mutate(
        .group = {
          observed <- unique(as.character(stats::na.omit(.data[[input$group]])))
          selected <- group_order_memory()
          selected <- selected[selected %in% observed]
          if(length(selected) < 2) selected <- observed
          factor(as.character(.data[[input$group]]), levels = selected)
        },
        .outcome_original = .data[[input$outcome]]
      )

    shiny::validate(shiny::need(nlevels(out$.group) >= 2, "Select at least two included groups."))
    out <- out |> dplyr::filter(!is.na(.group))
    if (isTRUE(input$drop_na)) {
      out <- out |>
        tidyr::drop_na(.group, .outcome_original)
    }

    if (input$strategy == "cfu_detection") {
      converted <- binary_event_from_values(out$.outcome_original)
      shiny::validate(shiny::need(any(is.finite(converted)),"CFU detection requires a numeric CFU column or a recognizable Yes/No detection column."))
      out <- out |> dplyr::mutate(.outcome = converted)
    } else if (input$strategy == "pm_incidence") {
      shiny::validate(shiny::need(is.numeric(out$.outcome_original),"Postmortem incidence requires a numeric score."))
      out <- out |> dplyr::mutate(.outcome=as.integer(.outcome_original>0))
    } else if (input$strategy == "cfu_full") {
      shiny::validate(shiny::need(is.numeric(out$.outcome_original),"Full CFU burden requires a numeric CFU count/burden column."))
      out <- out |> dplyr::mutate(.outcome=transform_outcome(.outcome_original,input$transformation,input$offset %||% 1))
    } else if (input$strategy == "cfu_positive") {
      shiny::validate(shiny::need(is.numeric(out$.outcome_original),"Positive CFU burden requires a numeric source outcome."))
      out <- out |> dplyr::filter(.outcome_original > 0) |>
        dplyr::mutate(.outcome=if(!grepl("log",input$outcome,ignore.case=TRUE))log10(as.numeric(.outcome_original))else as.numeric(.outcome_original))
    } else if (input$strategy == "pm_positive") {
      shiny::validate(shiny::need(is.numeric(out$.outcome_original),"Postmortem severity requires a numeric score."))
      out <- out |> dplyr::filter(.outcome_original > 0) |>
        dplyr::mutate(.outcome=transform_outcome(.outcome_original,input$transformation,input$offset %||% 1))
    } else if (input$outcome_type == "Numeric") {
      shiny::validate(shiny::need(is.numeric(out$.outcome_original), "Select a numeric outcome or choose Binary."))
      out <- out |> dplyr::mutate(.outcome = transform_outcome(.outcome_original,input$transformation,input$offset %||% 1))
    } else {
      shiny::req(input$event_level)
      out <- out |> dplyr::mutate(.outcome = as.integer(as.character(.outcome_original) == input$event_level))
    }
    out <- out |> tidyr::drop_na(.outcome)

    minimum_n <- max(2L, as.integer(input$minimum_group_n %||% 2L))
    group_counts <- out |>
      dplyr::count(.group, name = "usable_n", .drop = FALSE)
    keep_groups <- group_counts |>
      dplyr::filter(usable_n >= minimum_n) |>
      dplyr::pull(.group) |>
      as.character()

    if (isTRUE(input$drop_sparse_groups)) {
      out <- out |>
        dplyr::filter(as.character(.group) %in% keep_groups)
    }

    out$.group <- droplevels(out$.group)
    shiny::validate(
      shiny::need(
        nlevels(out$.group) >= 2,
        paste0(
          "Fewer than two groups meet the minimum of ", minimum_n,
          " usable observations. Lower the minimum or choose another outcome."
        )
      ),
      shiny::need(nrow(out) >= 4, "At least four usable observations across retained groups are required.")
    )
    out
  })

  group_qc <- shiny::reactive({
    x <- raw_data()
    shiny::req(x, input$group, input$outcome)
    base <- x |>
      dplyr::transmute(
        .group = factor(.data[[input$group]]),
        .outcome_original = .data[[input$outcome]]
      )
    if (input$strategy %in% c("cfu_positive","pm_positive")) {
      if(is.numeric(base$.outcome_original)) base <- base |> dplyr::filter(.outcome_original > 0) else base <- base[0,,drop=FALSE]
    }
    minimum_n <- max(2L, as.integer(input$minimum_group_n %||% 2L))
    base |>
      dplyr::filter(!is.na(.group), !is.na(.outcome_original)) |>
      dplyr::count(.group, name = "usable_n", .drop = FALSE) |>
      dplyr::mutate(
        minimum_n = minimum_n,
        status = dplyr::if_else(
          usable_n >= minimum_n,
          "Included",
          "Excluded: too few usable observations"
