  effective_type <- shiny::reactive({
    if(input$strategy %in% c("cfu_detection","pm_incidence")) "Binary" else
      if(input$strategy %in% c("cfu_full","cfu_positive","pm_positive","pm_full")) "Numeric" else input$outcome_type
  })

  selected_global_test <- shiny::reactive({
    dat <- analysis_data(); k <- nlevels(droplevels(dat$.group))
    requested <- input$global_test
    if(input$strategy=="cfu_detection") return("Fisher exact")
    if(input$strategy %in% c("cfu_full","cfu_positive")) return(if(k==2) "Mann-Whitney-Wilcoxon" else "Kruskal-Wallis")
    if (effective_type() == "Binary") return(if(requested == "Chi-square") "Chi-square" else "Fisher exact")
    zero_fraction <- mean(dat$.outcome == 0, na.rm=TRUE)
    pooled_skew <- {x<-dat$.outcome; m<-mean(x); z<-stats::sd(x); if(is.finite(z)&&z>0) mean(((x-m)/z)^3) else 0}
    nonparametric <- identical(input$transformation,"Rank") || zero_fraction > 0.35 || abs(pooled_skew) > 2
    if(k == 2) {
      if(requested %in% c("Kruskal-Wallis","Mann-Whitney-Wilcoxon")) return("Mann-Whitney-Wilcoxon")
      if(requested %in% c("ANOVA","Pooled t-test")) return("Pooled t-test")
      if(requested %in% c("Welch ANOVA","Welch t-test")) return("Welch t-test")
      return(if(nonparametric) "Mann-Whitney-Wilcoxon" else "Welch t-test")
    }
    if(requested != "Auto") {
      if(requested == "Mann-Whitney-Wilcoxon") return("Kruskal-Wallis")
      if(requested == "Welch t-test") return("Welch ANOVA")
      if(requested == "Pooled t-test") return("ANOVA")
      return(requested)
    }
    if(nonparametric) "Kruskal-Wallis" else "Welch ANOVA"
  })
  selected_posthoc_test <- shiny::reactive({
    dat<-analysis_data(); k<-nlevels(droplevels(dat$.group))
    if(input$strategy=="cfu_detection") return("Fisher exact")
    if(input$strategy %in% c("cfu_full","cfu_positive")) return(if(k==2) "Mann-Whitney-Wilcoxon" else "Dunn test")
    if(effective_type()=="Binary") return("Fisher exact")
    global<-selected_global_test()
    if(k==2) {
      if(global=="Mann-Whitney-Wilcoxon") return("Mann-Whitney-Wilcoxon")
      if(global=="Pooled t-test") return("Pooled t-test")
      return("Welch t-test")
    }
    if(input$posthoc_test!="Auto") return(input$posthoc_test)
    if(global=="Kruskal-Wallis") "Dunn test" else if(global=="ANOVA") "Tukey HSD" else "Welch t-test"
  })
  descriptive_summary <- shiny::reactive({
