  multi_outcome_bundle <- shiny::reactive({
    shiny::req(isTRUE(input$multi_outcome))
    x <- raw_data()
    shiny::req(x, input$group, input$group %in% names(x))
    vars <- setdiff(input$multi_outcomes %||% character(), input$group)
    vars <- intersect(vars, names(x))
    shiny::validate(shiny::need(length(vars) > 0, "Select at least one outcome."))
    observed <- ordered_group_levels(x[[input$group]])
    selected <- group_order_memory()
    selected <- selected[selected %in% observed]
    if (length(selected) < 2) selected <- observed
    shiny::validate(shiny::need(length(selected) >= 2, "Select at least two included groups."))
    g_all <- factor(as.character(x[[input$group]]), levels = selected)
    prepare_endpoint <- function(v) {
      original <- x[[v]]
      ok <- !is.na(g_all)
      if (isTRUE(input$drop_na)) ok <- ok & !is.na(original)
      original <- original[ok]
      g <- droplevels(g_all[ok])
      if (!length(original)) return(list(error = "No usable rows."))
      strategy <- input$strategy %||% "manual"
      binary_col <- !is.numeric(original)
      y <- NULL
      if (strategy == "cfu_detection") {
        y <- binary_event_from_values(original)
        if (!any(is.finite(y))) return(list(error = "CFU detection could not be coded."))
        binary_col <- TRUE
      } else if (strategy == "pm_incidence") {
        if (!is.numeric(original)) return(list(error = "Skipped: incidence needs a numeric score."))
        y <- as.integer(original > 0)
        binary_col <- TRUE
      } else if (strategy == "cfu_full") {
        if (!is.numeric(original)) return(list(error = "Skipped: full CFU needs a numeric column."))
        y <- tryCatch(transform_outcome(original, input$transformation %||% "None", input$offset %||% 1), error = function(e) e)
        if (inherits(y, "error")) return(list(error = conditionMessage(y)))
        binary_col <- FALSE
      } else if (strategy == "cfu_positive") {
        if (!is.numeric(original)) return(list(error = "Skipped: positive CFU needs a numeric column."))
        keep <- is.finite(original) & original > 0
        original <- original[keep]
        g <- droplevels(g[keep])
        y <- if (!grepl("log", v, ignore.case = TRUE)) log10(as.numeric(original)) else as.numeric(original)
        binary_col <- FALSE
      } else if (strategy == "pm_positive") {
        if (!is.numeric(original)) return(list(error = "Skipped: severity needs a numeric score."))
        keep <- is.finite(original) & original > 0
        original <- original[keep]
        g <- droplevels(g[keep])
        y <- tryCatch(transform_outcome(original, input$transformation %||% "None", input$offset %||% 1), error = function(e) e)
        if (inherits(y, "error")) return(list(error = conditionMessage(y)))
        binary_col <- FALSE
      } else if (!binary_col) {
        y <- tryCatch(transform_outcome(original, input$transformation %||% "None", input$offset %||% 1), error = function(e) e)
        if (inherits(y, "error")) return(list(error = conditionMessage(y)))
        if (identical(input$outcome_type, "Binary") && identical(v, input$outcome)) {
          y <- as.integer(as.character(original) == (input$event_level %||% ""))
          binary_col <- TRUE
        }
      } else {
        yy <- factor(as.character(original))
        if (nlevels(yy) != 2) return(list(error = "Skipped: needs exactly two categories."))
        event <- if (identical(v, input$outcome) && nzchar(input$event_level %||% "")) input$event_level else levels(yy)[2]
        if (!event %in% levels(yy)) event <- levels(yy)[2]
        y <- as.integer(yy == event)
        binary_col <- TRUE
      }
      keep <- is.finite(y) & !is.na(g)
      y <- y[keep]
      g <- droplevels(g[keep])
      minimum_n <- max(2L, as.integer(input$minimum_group_n %||% 2L))
      if (isTRUE(input$drop_sparse_groups)) {
        counts <- table(g)
        keep_g <- names(counts)[as.integer(counts) >= minimum_n]
        ok2 <- g %in% keep_g
        y <- y[ok2]
        g <- droplevels(g[ok2])
      }
      if (nlevels(g) < 2 || length(y) < 4) return(list(error = "Fewer than two usable groups."))
      list(data = tibble::tibble(.group = g, .outcome = y), binary = binary_col, error = NULL)
    }
    choose_global <- function(dat, k, binary) {
      requested <- input$global_test
      if (input$strategy == "cfu_detection") return("Fisher exact")
      if (input$strategy %in% c("cfu_full", "cfu_positive")) return(if (k == 2) "Mann-Whitney-Wilcoxon" else "Kruskal-Wallis")
      if (binary) return(if (identical(requested, "Chi-square")) "Chi-square" else "Fisher exact")
      zero_fraction <- mean(dat$.outcome == 0, na.rm = TRUE)
      pooled_skew <- { zdat <- dat$.outcome; m <- mean(zdat); z <- stats::sd(zdat); if (is.finite(z) && z > 0) mean(((zdat - m) / z)^3) else 0 }
      nonparametric <- identical(input$transformation, "Rank") || zero_fraction > 0.35 || abs(pooled_skew) > 2
      if (k == 2) {
        if (requested %in% c("Kruskal-Wallis", "Mann-Whitney-Wilcoxon")) return("Mann-Whitney-Wilcoxon")
        if (requested %in% c("ANOVA", "Pooled t-test")) return("Pooled t-test")
        if (requested %in% c("Welch ANOVA", "Welch t-test")) return("Welch t-test")
        return(if (nonparametric) "Mann-Whitney-Wilcoxon" else "Welch t-test")
      }
      if (!identical(requested, "Auto")) {
        if (requested == "Mann-Whitney-Wilcoxon") return("Kruskal-Wallis")
        if (requested == "Welch t-test") return("Welch ANOVA")
        if (requested == "Pooled t-test") return("ANOVA")
        return(requested)
      }
      if (nonparametric) "Kruskal-Wallis" else "Welch ANOVA"
    }
    choose_posthoc <- function(k, binary, global) {
      if (input$strategy == "cfu_detection") return("Fisher exact")
      if (input$strategy %in% c("cfu_full", "cfu_positive")) return(if (k == 2) "Mann-Whitney-Wilcoxon" else "Dunn test")
      if (binary) return("Fisher exact")
      if (k == 2) {
        if (global == "Mann-Whitney-Wilcoxon") return("Mann-Whitney-Wilcoxon")
        if (global == "Pooled t-test") return("Pooled t-test")
        return("Welch t-test")
      }
      if (!identical(input$posthoc_test, "Auto")) return(input$posthoc_test)
      if (global == "Kruskal-Wallis") "Dunn test" else if (global == "ANOVA") "Tukey HSD" else "Welch t-test"
    }
    compute_global_p <- function(dat, test, binary) {
      tryCatch({
        if (binary || test %in% c("Fisher exact", "Chi-square")) {
          tab <- table(dat$.group, dat$.outcome)
          fit <- if (identical(test, "Chi-square")) suppressWarnings(stats::chisq.test(tab)) else stats::fisher.test(tab)
          return(unname(fit$p.value))
        }
        fit <- switch(
          test,
          "ANOVA" = stats::aov(.outcome ~ .group, data = dat),
          "Welch ANOVA" = stats::oneway.test(.outcome ~ .group, data = dat, var.equal = FALSE),
          "Kruskal-Wallis" = stats::kruskal.test(.outcome ~ .group, data = dat),
          "Mann-Whitney-Wilcoxon" = suppressWarnings(stats::wilcox.test(.outcome ~ .group, data = dat, exact = FALSE)),
          "Welch t-test" = stats::t.test(.outcome ~ .group, data = dat, var.equal = FALSE),
          "Pooled t-test" = stats::t.test(.outcome ~ .group, data = dat, var.equal = TRUE),
          stats::kruskal.test(.outcome ~ .group, data = dat)
        )
        if (inherits(fit, "aov")) unname(summary(fit)[[1]]$`Pr(>F)`[1]) else unname(fit$p.value)
      }, error = function(e) NA_real_)
    }
    summarise_endpoint <- function(dat, v, binary) {
      if (!binary) return(numeric_group_summary(dat$.outcome, dat$.group, v))
      dat |>
        dplyr::group_by(.group) |>
        dplyr::summarise(n = dplyr::n(), events = sum(.outcome), proportion = mean(.outcome), .groups = "drop") |>
        dplyr::rowwise() |>
        dplyr::mutate(ci = list(wilson_ci(events, n)), lower = ci[[1]][1], upper = ci[[1]][2]) |>
        dplyr::ungroup() |>
        dplyr::transmute(
          Outcome = v, Group = as.character(.group), n = n, Events = events,
          Proportion = round(proportion, 3), `Wilson 95% CI` = fmt_interval(lower, upper)
        )
    }

    pieces <- purrr::map(vars, function(v) {
      prepared <- prepare_endpoint(v)
      if (is.null(prepared) || !is.null(prepared$error)) {
        note <- if (is.null(prepared)) "Skipped." else prepared$error
        return(list(contrasts = tibble::tibble(), summary = tibble::tibble(Outcome = v, Note = note)))
      }
      dat <- prepared$data
      binary <- isTRUE(prepared$binary)
      k <- nlevels(dat$.group)
      global <- choose_global(dat, k, binary)
      posthoc <- choose_posthoc(k, binary, global)
      adjust <- input$adjust_method %||% "holm"
      global_p <- compute_global_p(dat, global, binary)
      tab <- tryCatch({
        if (posthoc == "Dunn test") {
          pairwise_dunn(dat, adjust)
        } else if (posthoc %in% c("Tukey HSD", "Dunnett vs control")) {
          pairwise_emmeans(dat, posthoc, input$control_group, if (binary) "Binary" else "Numeric")
        } else if (binary || posthoc == "Fisher exact") {
          pairwise_fisher(dat, ".group", ".outcome", adjust)
        } else {
          pairwise_numeric(dat, ".group", ".outcome", posthoc, adjust)
        }
      }, error = function(e) tibble::tibble())
      if (!nrow(tab)) return(list(contrasts = tibble::tibble(), summary = tibble::tibble(Outcome = v, Note = "No pairwise result.")))
      n_by <- table(dat$.group)
      parts <- strsplit(as.character(tab$Comparison), " vs ", fixed = TRUE)
      tab$`n comparison` <- vapply(parts, function(p) as.integer(n_by[p[1]] %||% NA_integer_), integer(1))
      tab$`n reference` <- vapply(parts, function(p) {
        ref <- if (length(p) >= 2) sub(" \\(.*$", "", p[2]) else NA_character_
        as.integer(n_by[ref] %||% NA_integer_)
      }, integer(1))
      if (!binary) {
        fx <- purrr::map_dfr(seq_along(parts), function(i) {
          pair <- parts[[i]]
          if (length(pair) != 2) {
            return(tibble::tibble(Comparison = tab$Comparison[i], `Cliff's delta` = NA_real_, `Hodges-Lehmann difference` = NA_real_, `HL 95% CI lower` = NA_real_, `HL 95% CI upper` = NA_real_, effect_label = ""))
          }
          xx <- dat$.outcome[dat$.group == pair[1]]
          yy <- dat$.outcome[dat$.group == pair[2]]
          loc <- location_contrast(xx, yy)
          tibble::tibble(
            Comparison = tab$Comparison[i],
            `Cliff's delta` = loc$delta,
            `Hodges-Lehmann difference` = loc$estimate,
            `HL 95% CI lower` = loc$lower,
            `HL 95% CI upper` = loc$upper,
            effect_label = score_effect_label(xx, yy, loc)
          )
        })
        tab <- dplyr::left_join(tab, fx, by = "Comparison")
        tab$`Odds ratio` <- NA_real_
        tab$`OR 95% CI lower` <- NA_real_
        tab$`OR 95% CI upper` <- NA_real_
        tab$scale <- "location"
      } else {
        tab$`Cliff's delta` <- NA_real_
        tab$`Hodges-Lehmann difference` <- NA_real_
        tab$`HL 95% CI lower` <- NA_real_
        tab$`HL 95% CI upper` <- NA_real_
        if (!"OR" %in% names(tab)) tab$OR <- NA_real_
        if (!"Lower" %in% names(tab)) tab$Lower <- NA_real_
        if (!"Upper" %in% names(tab)) tab$Upper <- NA_real_
        tab$`Odds ratio` <- tab$OR
        tab$`OR 95% CI lower` <- tab$Lower
        tab$`OR 95% CI upper` <- tab$Upper
        tab$scale <- "odds ratio"
        tab$effect_label <- ""
      }
      tab$Outcome <- v
      tab$`Global test` <- global
      tab$`Global P` <- global_p
      tab$`Pairwise test` <- posthoc
      tab$p_individual <- tab$p_adjusted
      list(contrasts = tab, summary = summarise_endpoint(dat, v, binary))
    })
    contrasts <- dplyr::bind_rows(purrr::map(pieces, "contrasts"))
    shiny::validate(shiny::need(nrow(contrasts) > 0, "None of the selected variables had two usable groups."))
    method <- input$adjust_method %||% "holm"
    family_mode <- input$multi_family %||% "within_outcome"
    if (!family_mode %in% c("within_outcome", "global_outcomes", "all_pairs")) family_mode <- "within_outcome"
    contrasts$global_p <- contrasts$`Global P`
    if (family_mode == "all_pairs") {
      contrasts$p_adjusted <- stats::p.adjust(contrasts$p_raw, method = method)
    } else if (family_mode == "global_outcomes") {
      gmap <- contrasts |>
        dplyr::distinct(Outcome, .keep_all = TRUE) |>
        dplyr::mutate(p_global_adjusted = stats::p.adjust(global_p, method = method)) |>
        dplyr::select(Outcome, p_global_adjusted)
      contrasts <- contrasts |>
        dplyr::left_join(gmap, by = "Outcome") |>
        dplyr::mutate(p_adjusted = p_global_adjusted) |>
        dplyr::select(-p_global_adjusted)
    } else {
      contrasts$p_adjusted <- contrasts$p_individual
    }
    contrasts <- contrasts |>
      dplyr::mutate(
        `Raw P` = fmt_p(p_raw),
        `Adjusted P` = fmt_p(p_adjusted),
        `Global P` = fmt_p(global_p),
        `Effect (95% CI)` = dplyr::if_else(
          scale == "odds ratio",
          paste0("OR ", fmt_num(`Odds ratio`, 2), " (", fmt_interval(`OR 95% CI lower`, `OR 95% CI upper`, 2), ")"),
          dplyr::if_else(
            nzchar(effect_label),
            effect_label,
            paste0(fmt_num(`Hodges-Lehmann difference`), " (", fmt_interval(`HL 95% CI lower`, `HL 95% CI upper`), ")")
          )
        ),
        `Hodges-Lehmann difference (95% CI)` = dplyr::if_else(
          scale == "odds ratio" | !is.finite(`Hodges-Lehmann difference`),
          "",
          paste0(fmt_num(`Hodges-Lehmann difference`), " (", fmt_interval(`HL 95% CI lower`, `HL 95% CI upper`), ")")
        ),
        `Cliff's delta` = round(`Cliff's delta`, 3)
      ) |>
      dplyr::arrange(p_adjusted, p_raw, Outcome, Comparison)
    list(
      contrasts = contrasts,
      summary = dplyr::bind_rows(purrr::map(pieces, "summary")),
      reference = selected[1],
      family = family_mode,
      method = method
    )
  })

  multi_forest_plot <- shiny::reactive({
    bundle <- multi_outcome_bundle()
    z <- bundle$contrasts |>
      dplyr::filter(is.finite(p_adjusted))
    shiny::validate(shiny::need(nrow(z) > 0, "No estimable adjusted P values to plot."))
    if (identical(bundle$family, "global_outcomes")) {
      z <- z |> dplyr::group_by(Outcome) |> dplyr::slice(1) |> dplyr::ungroup()
      z$Label <- paste0(z$Outcome, "    P ", z$`Adjusted P`)
      z$Comparison <- "Global test"
    } else {
      z$Label <- paste0(z$Outcome, " · ", z$Comparison, "    P ", z$`Adjusted P`)
    }
    z$p_plot <- pmax(z$p_adjusted, 1e-300)
    z$Label <- factor(z$Label, levels = rev(unique(z$Label)))
    family_note <- switch(
      bundle$family,
      within_outcome = "Family: same adjusted P as each outcome analysed alone.",
      global_outcomes = "Family: one global test per outcome.",
      all_pairs = "Family: every pairwise comparison together.",
      "Family: pairwise tests within each outcome."
    )
    p <- ggplot2::ggplot(z, ggplot2::aes(x = p_plot, y = Label)) +
      ggplot2::geom_vline(xintercept = 0.05, linetype = 2) +
      ggplot2::scale_x_log10(
        breaks = c(0.001, 0.01, 0.05, 0.1, 1),
        labels = c("0.001", "0.01", "0.05", "0.1", "1"),
        expand = ggplot2::expansion(mult = c(0.08, 0.12))
      ) +
      ggplot2::labs(
        title = "Multiple-outcome adjusted P values",
        subtitle = paste(family_note, "Dashed line is 0.05. Effect sizes are in the results table."),
        x = "Adjusted P (log scale)",
        y = NULL
      ) +
      make_theme(input$base_size)
    if (identical(bundle$family, "global_outcomes")) {
      p + ggplot2::geom_point(colour = "#1B4332", size = 3)
    } else {
      p + ggplot2::geom_point(ggplot2::aes(colour = Comparison), size = 3)
    }
  })

  global_test_result <- shiny::reactive({
    dat <- analysis_data()
    test <- selected_global_test()

    if (effective_type() == "Binary") {
      tab <- table(dat$.group, dat$.outcome)
      fit <- if (test == "Chi-square") {
        suppressWarnings(stats::chisq.test(tab))
      } else {
        stats::fisher.test(tab)
      }
      return(long_test_result(
        if (test == "Chi-square") "Chi-square" else "Fisher exact",
        statistic = unname(fit$statistic %||% NA_real_),
        df = if(length(fit$parameter)>1) paste(round(unname(fit$parameter),3),collapse=", ") else unname(fit$parameter %||% ""),
        p = fit$p.value
      ))
    }

    fit <- switch(
      test,
      "ANOVA" = stats::aov(.outcome ~ .group, data = dat),
      "Welch ANOVA" = stats::oneway.test(.outcome ~ .group, data = dat, var.equal = FALSE),
      "Kruskal-Wallis" = stats::kruskal.test(.outcome ~ .group, data = dat),
      "Mann-Whitney-Wilcoxon" = suppressWarnings(stats::wilcox.test(.outcome ~ .group, data=dat, exact=FALSE)),
      "Welch t-test" = stats::t.test(.outcome ~ .group, data=dat, var.equal=FALSE),
      "Pooled t-test" = stats::t.test(.outcome ~ .group, data=dat, var.equal=TRUE),
      stats::kruskal.test(.outcome ~ .group, data = dat)
    )

    if (inherits(fit, "aov")) {
      sm <- summary(fit)[[1]]
      long_test_result(
        "ANOVA",
        statistic = sm$`F value`[1],
        df = paste0(sm$Df[1], ", ", sm$Df[2]),
        p = sm$`Pr(>F)`[1]
      )
    } else {
      long_test_result(
        test,
        statistic = unname(fit$statistic),
        df = if(length(fit$parameter)>1) paste(round(unname(fit$parameter),3),collapse=", ") else unname(fit$parameter %||% ""),
        p = fit$p.value
      )
    }
  })

  posthoc_result <- shiny::reactive({
    dat <- analysis_data()
    method <- selected_posthoc_test()
    adjust <- input$adjust_method

    if (method == "Dunn test") {
      pairwise_dunn(dat, adjust_method = adjust)
    } else if (method %in% c("Tukey HSD", "Dunnett vs control")) {
      pairwise_emmeans(
        dat,
        method = method,
        control_group = input$control_group,
