  explore_posthoc_display <- shiny::reactive({
    base <- posthoc_result()
    if (!nrow(base) || identical(effective_type(), "Binary")) return(base)
    dat <- analysis_data()
    g <- droplevels(dat$.group)
    y <- dat$.outcome
    parts <- strsplit(as.character(base$Comparison), " vs ", fixed = TRUE)
    fx <- purrr::map_dfr(seq_along(parts), function(i) {
      pair <- parts[[i]]
      if (length(pair) != 2) {
        return(tibble::tibble(
          Comparison = base$Comparison[i],
          `Cliff's delta` = NA_real_,
          `Hodges-Lehmann difference (95% CI)` = ""
        ))
      }
      xx <- y[g == pair[1]]
      yy <- y[g == pair[2]]
      loc <- location_contrast(xx, yy)
      tibble::tibble(
        Comparison = base$Comparison[i],
        `Cliff's delta` = round(loc$delta, 3),
        `Hodges-Lehmann difference (95% CI)` = paste0(fmt_num(loc$estimate), " (", fmt_interval(loc$lower, loc$upper), ")")
      )
    })
    dplyr::left_join(base, fx, by = "Comparison")
  })

