  output$download_plot_cart <- shiny::downloadHandler(
    filename = function() paste0("plot_cart_", Sys.Date(), ".zip"),
    contentType = "application/zip",
    content = function(file) {
      items <- plot_cart()
      shiny::validate(shiny::need(length(items) > 0, "The plot cart is empty."))
      export_dir <- tempfile("plot_cart_export_")
      dir.create(export_dir, recursive=TRUE, showWarnings=FALSE)
      on.exit(unlink(export_dir, recursive=TRUE, force=TRUE), add=TRUE)
      manifest <- vector("list", length(items))
      errors <- list()
      for (i in seq_along(items)) {
        item <- items[[i]]
        title <- item$title %||% ""
        if (!nzchar(trimws(title))) title <- paste("Plot", i)
        stem <- safe_name(title)
        if (!nzchar(stem)) stem <- paste0("plot_", i)
        file_name <- sprintf("%02d_%s.png", i, stem)
        width <- suppressWarnings(as.numeric(item$width %||% 7)); if(!is.finite(width) || width <= 0) width <- 7
        height <- suppressWarnings(as.numeric(item$height %||% 5)); if(!is.finite(height) || height <= 0) height <- 5
        dpi <- suppressWarnings(as.numeric(item$dpi %||% 300)); if(!is.finite(dpi) || dpi <= 0) dpi <- 300
        ok <- tryCatch({
          if(!is.null(item$plot_fun)){ragg::agg_png(file.path(export_dir,file_name),width=width,height=height,units="in",res=dpi,background="white");item$plot_fun();grDevices::dev.off()}else{ggplot2::ggsave(filename=file.path(export_dir,file_name),plot=item$plot,device=ragg::agg_png,width=width,height=height,units="in",dpi=dpi,bg="white")}
          file.exists(file.path(export_dir,file_name)) && file.info(file.path(export_dir,file_name))$size > 0
        }, error=function(e){errors[[length(errors)+1L]] <<- tibble::tibble(Item=i,Title=title,Error=conditionMessage(e));FALSE})
        manifest[[i]] <- tibble::tibble(Item=i,File=if(ok) file_name else NA_character_,Title=title,Width_in=width,Height_in=height,DPI=dpi,Status=if(ok) "Exported" else "Failed")
      }
      manifest_df <- dplyr::bind_rows(manifest)
      readr::write_csv(manifest_df,file.path(export_dir,"manifest.csv"))
      if(length(errors)) readr::write_csv(dplyr::bind_rows(errors),file.path(export_dir,"export_errors.csv"))
      exported <- manifest_df$Status == "Exported"
      shiny::validate(shiny::need(any(exported),"None of the saved plots could be exported. See the R console for the underlying graphics error."))
      files_to_zip <- list.files(export_dir,full.names=TRUE,all.files=FALSE)
      zip::zipr(zipfile=file,files=files_to_zip,root=export_dir,include_directories=FALSE)
      shiny::validate(shiny::need(file.exists(file) && file.info(file)$size > 0,"The ZIP archive could not be created."))
    }
  )

