  )

  output$download_xlsx <- shiny::downloadHandler(
    filename = function() paste0("veterinary_explorer_results_", Sys.Date(), ".xlsx"),
    content = function(file) {
      sheets <- list(
        filtered_data = analysis_data(),
        transformation_qc = transformation_qc(),
        descriptive_summary = descriptive_summary(),
        global_test = global_test_result(),
        posthoc = posthoc_result(),
        shapiro = shapiro_result(),
        group_inclusion_qc = group_qc()
      )
      if (isTRUE(input$enable_model)) {
        sheets$model_fixed_effects <- tryCatch(
          model_coefficient_table(adjusted_model()),
          error = function(e) tibble::tibble(Note = conditionMessage(e))
        )
        sheets$model_random_effects <- model_random_table(
          adjusted_model(),
          calculate_ci = isTRUE(input$random_effect_profile_ci)
        )
        sheets$model_adjusted_means <- model_emmeans_means_result()
        sheets$model_adjusted_comparisons <- model_emmeans_result()
      }
      writexl::write_xlsx(sheets, path = file)
    },
    contentType = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
  )

  reproducible_code <- shiny::reactive({
    group <- input$group
    outcome <- input$outcome
    transformation <- input$transformation
    offset <- input$offset %||% 1
    global <- selected_global_test()
    posthoc <- selected_posthoc_test()
    adjustment <- input$adjust_method
    control_group <- input$control_group %||% ""
    plot_type <- input$plot_type
    palette <- input$palette
    plot_style <- input$plot_style
    vertical_grid <- input$show_vertical_grid
    horizontal_grid <- input$show_horizontal_grid
    x_label <- input$x_label
    y_label <- input$y_label
    annotation_mode <- input$annotation_mode
    hide_ns <- input$hide_ns
    event <- input$event_level %||% "1"

    paste0(
      "# Reproducible analysis generated by Veterinary Biostatistics App\n",
      "# Generated: ", Sys.time(), "\n\n",
      "required <- c('dplyr','tidyr','readr','ggplot2','ggdist','scales','emmeans','rstatix')\n",
      "missing <- setdiff(required, rownames(installed.packages()))\n",
      "if (length(missing)) install.packages(missing)\n",
      "invisible(lapply(required, library, character.only = TRUE))\n\n",
      "d <- if (grepl('xlsx$', 'YOUR_DATA.xlsx', ignore.case=TRUE)) readxl::read_excel('YOUR_DATA.xlsx') else readr::read_csv('YOUR_DATA.csv', show_col_types=FALSE)\n",
      "group_var <- '", group, "'\n",
      "outcome_var <- '", outcome, "'\n",
      "outcome_type <- '", input$outcome_type, "'\n",
      "transformation <- '", transformation, "'\n",
      "offset <- ", offset, "\n",
      "event_level <- '", event, "'\n",
      "global_test <- '", global, "'\n",
      "posthoc_test <- '", posthoc, "'\n",
      "adjust_method <- '", adjustment, "'\n",
      "control_group <- '", control_group, "'\n",
      "plot_type <- '", plot_type, "'\n",
      "palette_name <- '", palette, "'\n",
      "plot_style <- '", plot_style, "'\n",
      "show_vertical_grid <- ", vertical_grid, "\n",
      "show_horizontal_grid <- ", horizontal_grid, "\n",
      "x_label <- '", x_label, "'\n",
      "y_label <- '", y_label, "'\n",
      "annotation_mode <- '", annotation_mode, "'\n",
      "hide_ns <- ", hide_ns, "\n\n",
      "dat <- d |>\n",
      "  dplyr::transmute(\n",
      "    group = factor(.data[[group_var]]),\n",
      "    outcome_original = .data[[outcome_var]]\n",
      "  ) |>\n",
      "  tidyr::drop_na()\n\n",
      "if (outcome_type == 'Numeric') {\n",
      "  dat <- dat |> dplyr::mutate(outcome = switch(\n",
      "    transformation,\n",
      "    'None' = as.numeric(outcome_original),\n",
      "    'log10(x + offset)' = log10(as.numeric(outcome_original) + offset),\n",
      "    'ln(x + offset)' = log(as.numeric(outcome_original) + offset),\n",
      "    'Square root' = sqrt(as.numeric(outcome_original)),\n",
      "    'Rank' = rank(as.numeric(outcome_original), ties.method = 'average')\n",
      "  ))\n",
      "} else {\n",
      "  dat <- dat |> dplyr::mutate(outcome = as.integer(as.character(outcome_original) == event_level))\n",
      "}\n\n",
      "# Global test\n",
      if (global == "Kruskal-Wallis") {
        "global_fit <- kruskal.test(outcome ~ group, data = dat)\n"
      } else if (global == "Mann-Whitney-Wilcoxon") {
        "global_fit <- wilcox.test(outcome ~ group, data = dat, exact = FALSE)\n"
      } else if (global == "Welch t-test") {
        "global_fit <- t.test(outcome ~ group, data = dat, var.equal = FALSE)\n"
      } else if (global == "Pooled t-test") {
        "global_fit <- t.test(outcome ~ group, data = dat, var.equal = TRUE)\n"
      } else if (global == "Welch ANOVA") {
        "global_fit <- oneway.test(outcome ~ group, data = dat, var.equal = FALSE)\n"
      } else if (global == "ANOVA") {
        "global_fit <- aov(outcome ~ group, data = dat)\n"
      } else if (global == "Chi-square") {
        "global_fit <- chisq.test(table(dat$group, dat$outcome))\n"
      } else {
        "global_fit <- fisher.test(table(dat$group, dat$outcome))\n"
      },
      "print(global_fit)\n\n",
      "# Pairwise post-hoc analysis\n",
      if (posthoc == "Dunn test") {
        paste0(
          "print(rstatix::dunn_test(dat, outcome ~ group, p.adjust.method = '", adjustment, "', detailed = TRUE))\n"
        )
      } else if (posthoc == "Tukey HSD") {
        paste0(
          "fit <- ", if (effective_type() == "Binary") "glm(outcome ~ group, family = binomial(), data = dat)" else "lm(outcome ~ group, data = dat)", "\n",
          "emm <- emmeans::emmeans(fit, ~ group)\n",
          "print(summary(emmeans::contrast(emm, method = 'pairwise', adjust = 'tukey'), infer = c(TRUE, TRUE)))\n"
        )
      } else if (posthoc == "Dunnett vs control") {
        paste0(
          "fit <- ", if (effective_type() == "Binary") "glm(outcome ~ group, family = binomial(), data = dat)" else "lm(outcome ~ group, data = dat)", "\n",
          "emm <- emmeans::emmeans(fit, ~ group)\n",
          "ref_index <- match(control_group, levels(dat$group))\n",
          "print(summary(emmeans::contrast(emm, method = 'trt.vs.ctrl', ref = ref_index, adjust = 'mvt'), infer = c(TRUE, TRUE)))\n"
        )
      } else if (posthoc == "Mann-Whitney-Wilcoxon") {
        paste0("print(pairwise.wilcox.test(dat$outcome, dat$group, p.adjust.method = '", adjustment, "', exact = FALSE))\n")
      } else if (posthoc == "Welch t-test") {
        paste0("print(pairwise.t.test(dat$outcome, dat$group, p.adjust.method = '", adjustment, "', pool.sd = FALSE))\n")
      } else if (posthoc == "Pooled t-test") {
        paste0("pairs <- combn(levels(dat$group),2,simplify=FALSE)\nraw_p <- sapply(pairs,function(g) t.test(outcome ~ droplevels(group),data=dat[dat$group %in% g,],var.equal=TRUE)$p.value)\nprint(data.frame(comparison=sapply(pairs,paste,collapse=' vs '),raw_p=raw_p,adjusted_p=p.adjust(raw_p,method='",adjustment,"')))\n")
      } else {
        paste0(
          "group_pairs <- combn(levels(dat$group), 2, simplify = FALSE)\n",
          "raw_p <- sapply(group_pairs, function(g) fisher.test(table(droplevels(dat$group[dat$group %in% g]), dat$outcome[dat$group %in% g]))$p.value)\n",
          "data.frame(comparison = sapply(group_pairs, paste, collapse = ' vs '), raw_p = raw_p, adjusted_p = p.adjust(raw_p, method = '", adjustment, "'))\n"
        )
      },
      "\n# Current plot preference: ", plot_type, "\n",
      "# Show n on plot: ", isTRUE(input$show_n_on_plot), "\n",
      "# Group colours: ", paste(names(active_group_colours()), active_group_colours(), sep="=", collapse=", "), "\n",
      if (isTRUE(input$enable_model)) paste0(
        "\n# Adjusted model\n",
        "# Formula: ", adjusted_model()$formula, "\n",
        "# Model type: ", input$model_type, "\n",
        "# Interactions: ", paste(input$interaction_terms %||% character(), collapse=", "), "\n",
        "# Refit with lme4::lmer/glmer or stats::lm/glm as specified above.\n"
      ) else ""
    )
  })

  output$download_code <- shiny::downloadHandler(
    filename = function() paste0("reproducible_analysis_", Sys.Date(), ".R"),
    content = function(file) {
      writeLines(reproducible_code(), file, useBytes = TRUE)
    },
    contentType = "text/plain"
  )
}

